// Good Code: Validating and sanitizing user input to prevent path traversal
import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class FileDownloadSecure {
    public void downloadFile(String filename) {
        String basePath = "/var/www/html/downloads/";

        // Validate that the filename does not contain path separators or dots for parent directories
        if (filename.contains("..") || filename.contains("/") || filename.contains("\\")) {
            throw new IllegalArgumentException("Invalid filename");
        }

        // Construct the full path and verify it stays within the base directory
        Path fullPath = Paths.get(basePath).resolve(filename).normalize();
        Path normalizedBase = Paths.get(basePath).normalize();

        if (!fullPath.startsWith(normalizedBase)) {
            throw new SecurityException("Access denied: Attempted path traversal detected.");
        }

        File file = fullPath.toFile();
        if (file.exists()) {
            System.out.println("Downloading " + file.getAbsolutePath());
        }
    }
}
